<script setup lang="ts">
import { computed, ref } from "vue"
import { useRouter } from "vue-router"
import HotelCard from "../components/HotelCard.vue"
import { hotels } from "../Data/Hotel"

const router = useRouter()

const checkIn = ref("")
const checkOut = ref("")
const error = ref("")

const featuredHotels = computed(() => hotels.slice(0, 3))

const searchHotels = () => {
  if (!checkIn.value || !checkOut.value) {
    error.value = "Please select both check-in and check-out dates."
    return
  }
  if (checkOut.value <= checkIn.value) {
    error.value = "Check-out date must be after the check-in date."
    return
  }
  error.value = ""
  router.push({
    path: "/hotel",
    query: { checkin: checkIn.value, checkout: checkOut.value }
  })
}
</script>